{
  "description": "The creature is a large hybrid standing upright on two hind legs in profile facing right, with the overall body, head, fur, legs and tail of a tawny lioness and a pair of very large outstretched bird wings attached at the shoulders and back. Its fur is short and tawny-brown with a lighter cream underbelly and muzzle, and its wings are broad and fully spread to either side, covered in dense layered feathers in shades of brown, tan, cream and gray. The animal is posed with its hind legs bent and its wings held open, showing detailed musculature and feather texture against a plain light background.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a lioness head in right profile with tawny fur, a pale cream muzzle and chin, a pinkish-brown nose, amber eyes with dark pupils, white whiskers, and a calm expression",
      "where": "at the top front of the body on top of a thick neck"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded furry ears with tawny outer fur and darker brown interior, one seen clearly in profile and the other partially visible behind it",
      "where": "on the top of the head"
    },
    {
      "part": "legs",
      "looks_like": "two thick muscular hind legs covered in short tawny fur with lighter fur on the inner thigh, bent at the knee and hock in a standing crouch",
      "where": "under the torso extending down to the ground, one slightly in front of the other"
    },
    {
      "part": "feet",
      "looks_like": "two large feline paws with tawny fur, visible toe pads and short dark claws",
      "where": "at the bottom ends of the hind legs resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long slender tail covered in short tawny fur ending in a darker brown bushy tuft",
      "where": "extending from the rear of the hindquarters back and to the left, curving down to near the ground"
    },
    {
      "part": "wings",
      "looks_like": "two very large broad wings fully outstretched to the sides, with layered flight feathers that are dark brown at the tips fading to tan, cream and gray toward the base",
      "where": "attached at the shoulder and back area, one extending to the left and one to the right of the body"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping feathers with detailed barbs in brown, tan and gray tones, covering the entire wing surface and continuing as smaller scale-like feathers over the chest and shoulder area",
      "where": "covering both wings and the upper chest and shoulder region"
    }
  ],
  "attached_objects": [],
  "animals": [
    "lion",
    "eagle"
  ],
  "separate_bodies": 1,
